import React, { useEffect, useState } from "react";
import axios from "axios";

const Dashboard = () => {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);


  // ==========================
  // 🔒 PROTECT ROUTE
  // ==========================
  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      window.location.href = "/login";
    }
  }, []);


  // ==========================
  // 📄 FETCH RESUMES
  // ==========================
  const fetchResumes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await axios.get(
        "http://localhost:5000/api/resume/my",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setResumes(res.data);

    } catch (err) {
      console.error(err);
      localStorage.removeItem("token");
      window.location.href = "/login";
    } finally {
      setLoading(false);
    }
  };


  // ==========================
  // 👤 FETCH USER
  // ==========================
  const fetchUser = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await axios.get(
        "http://localhost:5000/api/auth/me",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setUser(res.data);

    } catch (err) {
      console.log(err);
    }
  };


  // ==========================
  // 🚪 LOGOUT
  // ==========================
  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };


  // ==========================
  // 🔄 INITIAL LOAD
  // ==========================
  useEffect(() => {
    fetchResumes();
    fetchUser();
  }, []);


  return (
    <div style={styles.container}>

      {/* HEADER */}
      <div style={styles.header}>
        <div>
          <h2>Your Saved Resumes</h2>
          {user && <p>Welcome: {user.email}</p>}
        </div>

        <div>
          <button
            onClick={() => (window.location.href = "/")}
            style={styles.analyzeBtn}
          >
            Analyze Resume
          </button>

          <button onClick={handleLogout} style={styles.logoutBtn}>
            Logout
          </button>
        </div>
      </div>


      {/* CONTENT */}
      {loading ? (
        <p>Loading...</p>
      ) : resumes.length === 0 ? (
        <p>No resumes found</p>
      ) : (
        resumes.map((r, i) => (
          <div key={i} style={styles.card}>
            <h3>{r.name || "No Name"}</h3>
            <p><strong>ATS Score:</strong> {r.atsScore || 0}</p>
          </div>
        ))
      )}
    </div>
  );
};


// ======================
// STYLES
// ======================
const styles = {
  container: {
    padding: "20px",
    maxWidth: "800px",
    margin: "auto",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  },
  logoutBtn: {
    marginLeft: "10px",
    padding: "8px",
    background: "red",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  analyzeBtn: {
    padding: "8px",
    background: "#2563eb",
    color: "white",
    border: "none",
    cursor: "pointer",
  },
  card: {
    border: "1px solid #ccc",
    marginTop: "10px",
    padding: "10px",
    borderRadius: "5px",
  },
};

export default Dashboard;
